{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Levodopa absolute oral bioavailability was 80.4% in fasted healthy volunteers by direct IV comparison, supporting high F for a small polar oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "The active metabolite of nabumetone had 38% absolute oral bioavailability in healthy subjects, showing that even moderate first-pass metabolism still exceeds the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Metoclopramide, an aromatic amine drug, had 60% oral bioavailability in normal patients, supporting adequate absorption for aniline-like structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Meperidine oral bioavailability was 47-73% in healthy men despite ester/amine structure and first-pass metabolism, supporting high F for the query's carbamate/amine framework.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Diflunisal absolute oral bioavailability was 89.5%, and its fluorophenyl-aromatic structure supports high F for the fluorinated aromatic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Lemborexant was at least 87% bioavailable in healthy subjects and contains a fluorophenyl-amide motif, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental evidence, with high assay-transfer scores, reports oral bioavailability above 20% (range 32-99%). No evidence supports F below 20%, and the query's small molecular size and drug-like features are consistent with high oral bioavailability at this threshold.",
  "evidence_gaps": [
    "No direct human absolute bioavailability study exists for the query molecule.",
    "No analogue exactly matches the carbamate-aniline-benzylamine combination.",
    "First-pass metabolism of the aromatic amine or carbamate is not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

